import { createHash } from 'node:crypto'
import { readdirSync, readFileSync } from 'node:fs'
import { join } from 'node:path'

// Subresource Integrity hashes of the minified files in the dist folder of the smartmenus package
// (e.g. { 'css/smartmenus.min.css': 'sha384-...' }). The code generated by the configurator uses them for the CDN links.
export function getSriHashes(distDir) {
  const hashes = {}
  for (const directory of ['js', 'css']) {
    for (const name of readdirSync(join(distDir, directory))) {
      if (/\.min\.(js|css)$/.test(name)) {
        const digest = createHash('sha384')
          .update(readFileSync(join(distDir, directory, name)))
          .digest('base64')
        hashes[`${directory}/${name}`] = `sha384-${digest}`
      }
    }
  }
  return hashes
}
